/*!
 * ==========================================================
 * SaQshi Open Source
 * Global Table Pagination Helper
 * pagination.js
 * Version 1.0.0 | Updated 2026-07-13
 * ==========================================================
 */

(function (window, document) {
    "use strict";

    window.SQ = window.SQ || {};
    if (window.SQ.pagination && typeof window.SQ.pagination.create === "function") {
        return;
    }

    function toInt(value, fallback) {
        const parsed = Number.parseInt(value, 10);
        return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
    }

    function esc(value) {
        return String(value ?? "")
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;");
    }

    function create(options) {
        const state = {
            page: toInt(options?.page, 1),
            perPage: toInt(options?.perPage, 50),
            totalRows: toInt(options?.totalRows, 0),
            totalPages: toInt(options?.totalPages, 1)
        };
        const onChange = typeof options?.onChange === "function" ? options.onChange : function () {};

        function set(pagination) {
            state.page = toInt(pagination?.page, state.page);
            state.perPage = toInt(pagination?.per_page ?? pagination?.perPage, state.perPage);
            state.totalRows = Math.max(0, toInt(pagination?.total_rows ?? pagination?.totalRows, 0));
            state.totalPages = Math.max(1, toInt(pagination?.total_pages ?? pagination?.totalPages, 1));
            if (state.page > state.totalPages) state.page = state.totalPages;
            return api;
        }

        function params(extra) {
            return Object.assign({}, extra || {}, {
                page: state.page,
                per_page: state.perPage
            });
        }

        function render(container, label) {
            const el = typeof container === "string" ? document.getElementById(container) : container;
            if (!el) return api;

            const from = state.totalRows ? ((state.page - 1) * state.perPage) + 1 : 0;
            const to = Math.min(state.page * state.perPage, state.totalRows);

            el.innerHTML = state.totalRows
                ? `<div class="sq-state-pager" data-sq-pagination>
                    <span>${esc(label || "Showing")} ${esc(from)}-${esc(to)} of ${esc(state.totalRows)}</span>
                    <div>
                        <button class="sq-btn sq-btn-light" type="button" data-sq-page="prev" ${state.page <= 1 ? "disabled" : ""}>Previous</button>
                        <strong>Page ${esc(state.page)} / ${esc(state.totalPages)}</strong>
                        <button class="sq-btn sq-btn-light" type="button" data-sq-page="next" ${state.page >= state.totalPages ? "disabled" : ""}>Next</button>
                    </div>
                </div>`
                : "";

            el.querySelector("[data-sq-page='prev']")?.addEventListener("click", function () {
                if (state.page <= 1) return;
                state.page--;
                onChange(state);
            });
            el.querySelector("[data-sq-page='next']")?.addEventListener("click", function () {
                if (state.page >= state.totalPages) return;
                state.page++;
                onChange(state);
            });

            return api;
        }

        function reset() {
            state.page = 1;
            return api;
        }

        function getState() {
            return Object.assign({}, state);
        }

        const api = { set, params, render, reset, state: getState };
        return api;
    }

    window.SQ.pagination = { create };
})(window, document);

/*!
 * ==========================================================
 * Client-side upload helper
 * ----------------------------------------------------------
 * Module   : File Upload & Management Service
 * File     : upload.js
 * License  : GPL-3.0
 * ==========================================================
 *
 * PURPOSE
 * ----------------------------------------------------------
 * Centralized file management service.
 *
 * Never use:
 *
 *      fetch(file)
 *
 * directly.
 *
 * Always use:
 *
 *      SQ.upload.upload()
 *
 * FEATURES
 * ----------------------------------------------------------
 * ✔ Image Upload
 * ✔ PDF Upload
 * ✔ Excel Upload
 * ✔ Multiple Upload
 * ✔ Drag & Drop
 * ✔ Upload Progress
 * ✔ File Validation
 * ✔ Preview
 * ✔ Download
 * ✔ Delete
 * ✔ Retry
 * ✔ Queue
 * ✔ Future OCR
 * ✔ Future Compression
 * ✔ Future Virus Scan
 *
 * USED BY
 * ----------------------------------------------------------
 *
 * Assessment
 *      Evidence Images
 *
 * Action Plan
 *      Supporting Documents
 *
 * Gap Closure
 *      Closure Evidence
 *
 * Reports
 *      Excel Import
 *
 * AI
 *      OCR Documents
 *
 * ==========================================================
 */

(function (window) {

    "use strict";

    if (!window.SQ) {
        window.SQ = {};
    }

    const SQ = window.SQ;

    if (!SQ.api) {
        throw new Error("SQ.api must be loaded before upload.js");
    }

    const CONFIG = {

        endpoint: "/files/v1/upload.php",

        maxFileSize: 10 * 1024 * 1024,

        multiple: true,

        allowedTypes: [

            "image/jpeg",
            "image/png",
            "image/webp",
            "application/pdf",
            "application/msword",
            "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
            "application/vnd.ms-excel",
            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
            "text/csv",
            "application/csv"

        ]

    };

    function validate(file) {

        if (!file) {

            return {
                valid: false,
                message: "No file selected."
            };

        }

        if (file.size > CONFIG.maxFileSize) {

            return {

                valid: false,

                message: "Maximum upload size is 10 MB."

            };

        }

        if (

            CONFIG.allowedTypes.length &&
            !CONFIG.allowedTypes.includes(file.type)

        ) {

            return {

                valid: false,

                message: "Unsupported file type."

            };

        }

        return {

            valid: true

        };

    }

    async function upload(file, extraData = {}, options = {}) {

        const validation = validate(file);

        if (!validation.valid) {

            throw validation;

        }

        const formData = new FormData();

        formData.append("file", file);

        Object.keys(extraData).forEach(function (key) {

            formData.append(key, extraData[key]);

        });

        return SQ.api.upload(

            options.endpoint || CONFIG.endpoint,

            formData,

            {

                loaderText: "Uploading file..."

            }

        );

    }

    async function uploadMultiple(files, extraData = {}, options = {}) {

        const responses = [];

        for (const file of files) {

            responses.push(

                await upload(

                    file,

                    extraData,

                    options

                )

            );

        }

        return responses;

    }

    function preview(file, imageElement) {

        if (!(file instanceof File)) {

            return;

        }

        if (!file.type.startsWith("image/")) {

            return;

        }

        const reader = new FileReader();

        reader.onload = function (e) {

            imageElement.src = e.target.result;

        };

        reader.readAsDataURL(file);

    }

    function bindPreview(inputSelector, imageSelector) {

        const input = document.querySelector(inputSelector);

        const image = document.querySelector(imageSelector);

        if (!input || !image) {

            return;

        }

        input.addEventListener("change", function () {

            if (this.files.length) {

                preview(

                    this.files[0],

                    image

                );

            }

        });

    }

    function bindDropZone(dropSelector, inputSelector) {

        const zone = document.querySelector(dropSelector);

        const input = document.querySelector(inputSelector);

        if (!zone || !input) {

            return;

        }

        zone.addEventListener("dragover", function (e) {

            e.preventDefault();

            zone.classList.add("sq-drag-over");

        });

        zone.addEventListener("dragleave", function () {

            zone.classList.remove("sq-drag-over");

        });

        zone.addEventListener("drop", function (e) {

            e.preventDefault();

            zone.classList.remove("sq-drag-over");

            input.files = e.dataTransfer.files;

            input.dispatchEvent(

                new Event("change")

            );

        });

    }

    async function download(url, filename = "download") {

        return SQ.api.download(

            url,

            {},

            filename

        );

    }

    async function remove(fileRef) {

        const payload = String(fileRef || "").includes("/")
            ? { url: fileRef }
            : { file_id: fileRef };

        return SQ.api.delete(

            "/files/v1/delete.php",

            payload

        );

    }

    function humanSize(bytes) {

        const units = [

            "B",
            "KB",
            "MB",
            "GB"

        ];

        let i = 0;

        while (

            bytes >= 1024 &&
            i < units.length - 1

        ) {

            bytes /= 1024;

            i++;

        }

        return bytes.toFixed(2) + " " + units[i];

    }

    function extension(fileName) {

        return fileName.split(".").pop().toLowerCase();

    }

    SQ.upload = {

        config(settings = {}) {

            Object.assign(

                CONFIG,

                settings

            );

        },

        validate,

        upload,

        uploadMultiple,

        preview,

        bindPreview,

        bindDropZone,

        download,

        delete: remove,

        humanSize,

        extension

    };

})(window);

/*!
 * ==========================================================
 * Client-side validation helper
 * ----------------------------------------------------------
 * Module   : Form Validation Service
 * File     : validator.js
 * License  : GPL-3.0
 * ==========================================================
 *
 * PURPOSE
 * ----------------------------------------------------------
 * Central client-side validation service.
 *
 * Used for:
 * - Login form
 * - Assessment creation
 * - Department activation
 * - Assessor / assessee information
 * - Checklist response validation
 * - Action plan form
 * - Gap closure form
 * - Evidence upload form
 * - Reports filters
 * - Admin forms
 *
 * This does NOT replace backend validation.
 * Backend validation is always final.
 *
 * BASIC USAGE
 * ----------------------------------------------------------
 *
 * const result = SQ.validator.validate(form, {
 *     assessment_name: ["required", "min:3"],
 *     end_date: ["required", "date"],
 *     mobile: ["mobile"]
 * });
 *
 * if (!result.valid) {
 *     SQ.validator.showErrors(form, result.errors);
 * }
 *
 * ==========================================================
 */

(function (window, document) {
    "use strict";

    if (!window.SQ) {
        window.SQ = {};
    }

    const Validator = {};

    /* ======================================================
       Utility
    ====================================================== */

    function isEmpty(value) {
        return value === null ||
            value === undefined ||
            String(value).trim() === "";
    }

    function getValue(form, field) {
        const input = form.querySelector("[name='" + field + "']");

        if (!input) {
            return "";
        }

        if (input.type === "checkbox") {
            return input.checked ? input.value || true : "";
        }

        if (input.type === "radio") {
            const checked = form.querySelector("[name='" + field + "']:checked");
            return checked ? checked.value : "";
        }

        return input.value;
    }

    function getLabel(form, field) {
        const input = Array.from(form.querySelectorAll("[name]")).find(function (element) {
            return element.getAttribute("name") === field;
        });

        if (!input) {
            return field;
        }

        const id = input.getAttribute("id");

        if (id) {
            const label = Array.from(form.querySelectorAll("label[for]")).find(function (element) {
                return element.getAttribute("for") === id;
            });

            if (label) {
                return label.textContent.replace(/\*/g, "").trim();
            }
        }

        return input.getAttribute("data-label") || field;
    }

    function addError(errors, field, message) {
        if (!errors[field]) {
            errors[field] = message;
        }
    }

    /* ======================================================
       Rules
    ====================================================== */

    Validator.rules = {
        required: function (value) {
            return !isEmpty(value);
        },

        email: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
        },

        mobile: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return /^[6-9]\d{9}$/.test(String(value).trim());
        },

        number: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return !Number.isNaN(Number(value));
        },

        integer: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return Number.isInteger(Number(value));
        },

        decimal: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return /^\d+(\.\d{1,2})?$/.test(String(value).trim());
        },

        date: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return !Number.isNaN(Date.parse(value));
        },

        url: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            try {
                new URL(value);
                return true;
            } catch (e) {
                return false;
            }
        },

        nin: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return /^\d{10}$/.test(String(value).trim());
        },

        pincode: function (value) {
            if (isEmpty(value)) {
                return true;
            }

            return /^\d{6}$/.test(String(value).trim());
        }
    };

    /* ======================================================
       Validation Messages
    ====================================================== */

    Validator.messages = {
        required: "{label} is required",
        email: "{label} must be a valid email address",
        mobile: "{label} must be a valid 10 digit mobile number",
        number: "{label} must be a valid number",
        integer: "{label} must be a valid integer",
        decimal: "{label} must be a valid decimal value",
        date: "{label} must be a valid date",
        url: "{label} must be a valid URL",
        nin: "{label} must be a valid 10 digit NIN number",
        pincode: "{label} must be a valid 6 digit PIN code",
        min: "{label} must be at least {param} characters",
        max: "{label} must not be more than {param} characters",
        minValue: "{label} must be at least {param}",
        maxValue: "{label} must not be greater than {param}",
        match: "{label} does not match {param}",
        in: "{label} has invalid value"
    };

    function message(rule, label, param) {
        const template = Validator.messages[rule] || "{label} is invalid";

        return template
            .replace("{label}", label)
            .replace("{param}", param || "");
    }

    /* ======================================================
       Main Validate
    ====================================================== */

    Validator.validate = function (form, rules = {}) {
        const formEl = typeof form === "string"
            ? document.querySelector(form)
            : form;

        const errors = {};

        if (!formEl) {
            return {
                valid: false,
                errors: {
                    form: "Form not found"
                }
            };
        }

        Object.keys(rules).forEach(function (field) {
            const fieldRules = rules[field];
            const value = getValue(formEl, field);
            const label = getLabel(formEl, field);

            fieldRules.forEach(function (ruleText) {
                if (errors[field]) {
                    return;
                }

                const parts = String(ruleText).split(":");
                const rule = parts[0];
                const param = parts[1] || null;

                if (Validator.rules[rule]) {
                    if (!Validator.rules[rule](value, param)) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "min") {
                    if (!isEmpty(value) && String(value).length < Number(param)) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "max") {
                    if (!isEmpty(value) && String(value).length > Number(param)) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "minValue") {
                    if (!isEmpty(value) && Number(value) < Number(param)) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "maxValue") {
                    if (!isEmpty(value) && Number(value) > Number(param)) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "match") {
                    const otherValue = getValue(formEl, param);

                    if (value !== otherValue) {
                        addError(errors, field, message(rule, label, param));
                    }

                    return;
                }

                if (rule === "in") {
                    const allowed = String(param).split(",");

                    if (!allowed.includes(String(value))) {
                        addError(errors, field, message(rule, label, param));
                    }
                }
            });
        });

        return {
            valid: Object.keys(errors).length === 0,
            errors: errors
        };
    };

    /* ======================================================
       Show Errors
    ====================================================== */

    Validator.showErrors = function (form, errors = {}) {
        const formEl = typeof form === "string"
            ? document.querySelector(form)
            : form;

        if (!formEl) {
            return;
        }

        Validator.clearErrors(formEl);

        Object.keys(errors).forEach(function (field) {
            const input = formEl.querySelector("[name='" + field + "']");

            if (!input) {
                return;
            }

            input.classList.add("sq-is-invalid");
            input.setAttribute("aria-invalid", "true");

            let errorEl = input
                .closest(".sq-form-group")
                ?.querySelector(".sq-field-error");

            if (!errorEl) {
                errorEl = document.createElement("div");
                errorEl.className = "sq-field-error";
                errorEl.setAttribute("role", "alert");

                const group = input.closest(".sq-form-group");

                if (group) {
                    group.appendChild(errorEl);
                } else {
                    input.insertAdjacentElement("afterend", errorEl);
                }
            }

            errorEl.textContent = errors[field];
        });
    };

    /* ======================================================
       Clear Errors
    ====================================================== */

    Validator.clearErrors = function (form) {
        const formEl = typeof form === "string"
            ? document.querySelector(form)
            : form;

        if (!formEl) {
            return;
        }

        formEl.querySelectorAll(".sq-is-invalid").forEach(function (input) {
            input.classList.remove("sq-is-invalid");
            input.removeAttribute("aria-invalid");
        });

        formEl.querySelectorAll(".sq-field-error").forEach(function (error) {
            error.remove();
        });
    };

    /* ======================================================
       Validate And Show
    ====================================================== */

    Validator.validateAndShow = function (form, rules = {}) {
        const result = Validator.validate(form, rules);

        if (!result.valid) {
            Validator.showErrors(form, result.errors);
        } else {
            Validator.clearErrors(form);
        }

        return result;
    };

    /* ======================================================
       Custom Rule
    ====================================================== */

    Validator.addRule = function (name, callback, messageText) {
        Validator.rules[name] = callback;

        if (messageText) {
            Validator.messages[name] = messageText;
        }
    };

    /* ======================================================
       Predefined SaQshi Validation Sets
    ====================================================== */

    Validator.presets = {
        login: {
            username: ["required"],
            password: ["required"]
        },

        assessmentCreate: {
            assessment_name: ["required", "min:3", "max:150"],
            start_date: ["required", "date"],
            end_date: ["required", "date"]
        },

        assessorInfo: {
            assessment_date: ["required", "date"],
            assessor_name: ["required", "min:3"],
            assessee_name: ["required", "min:3"],
            assessor_mobile: ["mobile"],
            assessee_mobile: ["mobile"],
            assessor_email: ["email"],
            assessee_email: ["email"]
        },

        actionPlan: {
            user_action_plan: ["required", "min:3"],
            achievability: ["required", "in:ACHIEVABLE,NON_ACHIEVABLE"],
            priority: ["required", "in:LOW,MEDIUM,HIGH"],
            target_date: ["date"]
        },

        gapClosure: {
            closure_remarks: ["required", "min:3"],
            revised_score: ["number", "minValue:0", "maxValue:2"]
        }
    };

    window.SQ.validator = Validator;

})(window, document);

/* Browser-local queue for unsent checklist responses. No credentials or tokens are stored. */
(function (window) {
    "use strict";

    const DB_NAME = "saqshi-offline";
    const STORE = "response_queue";

    function database() {
        return new Promise(function (resolve, reject) {
            const request = indexedDB.open(DB_NAME, 1);
            request.onupgradeneeded = function () {
                const db = request.result;
                if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE, { keyPath: "id" });
            };
            request.onsuccess = function () { resolve(request.result); };
            request.onerror = function () { reject(request.error); };
        });
    }

    async function all() {
        const db = await database();
        return new Promise(function (resolve, reject) {
            const request = db.transaction(STORE, "readonly").objectStore(STORE).getAll();
            request.onsuccess = function () { resolve(request.result || []); db.close(); };
            request.onerror = function () { reject(request.error); db.close(); };
        });
    }

    async function put(item) {
        const db = await database();
        return new Promise(function (resolve, reject) {
            const request = db.transaction(STORE, "readwrite").objectStore(STORE).put(item);
            request.onsuccess = function () { resolve(); db.close(); };
            request.onerror = function () { reject(request.error); db.close(); };
        });
    }

    async function remove(id) {
        const db = await database();
        return new Promise(function (resolve, reject) {
            const request = db.transaction(STORE, "readwrite").objectStore(STORE).delete(id);
            request.onsuccess = function () { resolve(); db.close(); };
            request.onerror = function () { reject(request.error); db.close(); };
        });
    }

    window.SQ = window.SQ || {};
    window.SQ.offlineResponseQueue = {
        async enqueue(userId, payload) {
            const id = [userId || 0, payload.assessment_id, payload.dept_id, payload.checkpoint_id].join(":");
            await put({ id: id, user_id: Number(userId || 0), payload: payload, queued_at: Date.now() });
        },
        async count(userId) {
            return (await all()).filter(item => Number(item.user_id) === Number(userId || 0)).length;
        },
        async flush(userId, send) {
            const items = (await all()).filter(item => Number(item.user_id) === Number(userId || 0)).sort((a, b) => a.queued_at - b.queued_at);
            let sent = 0;
            for (const item of items) {
                await send(item.payload);
                await remove(item.id);
                sent++;
            }
            return sent;
        },
        /**
         * Send queued responses together for each assessment department.
         * A batch is removed only once the server has accepted every response
         * in it, so an interrupted reconnect can never lose local data.
         */
        async flushBatches(userId, send, batchSize = 250) {
            const items = (await all())
                .filter(item => Number(item.user_id) === Number(userId || 0))
                .sort((a, b) => a.queued_at - b.queued_at);
            const groups = new Map();

            items.forEach(function (item) {
                const payload = item.payload || {};
                const key = [payload.assessment_id, payload.dept_id].join(":");
                if (!groups.has(key)) groups.set(key, []);
                groups.get(key).push(item);
            });

            let sent = 0;
            for (const group of groups.values()) {
                for (let start = 0; start < group.length; start += batchSize) {
                    const batch = group.slice(start, start + batchSize);
                    await send(batch.map(item => item.payload));
                    for (const item of batch) await remove(item.id);
                    sent += batch.length;
                }
            }
            return sent;
        }
    };
})(window);

/*!
 * ==========================================================
 * SaQshi Deployment Config Client
 * deployment.js
 * Version 1.0.0 | Updated 2026-07-18
 * ==========================================================
 */
(function (window, document) {
    "use strict";

    window.SQ = window.SQ || {};
    const SQ = window.SQ;
    let cached = null;

    async function load(force = false) {
        if (cached && !force) {
            return cached;
        }

        if (!SQ.api || typeof SQ.api.get !== "function") {
            return null;
        }

        const response = await SQ.api.get("/config/v1/deployment.php", {}, {
            loader: false,
            showError: false,
            redirectOnUnauthorized: false
        });
        cached = response.data || null;
        SQ.deploymentConfig = cached;
        applyLabels(document);
        return cached;
    }

    function label(key, fallback = "") {
        return cached?.domain?.labels?.[key] || fallback || key;
    }

    function interpolate(value) {
        return String(value || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
            return label(key, key);
        });
    }

    function text(key, fallback = "") {
        return interpolate(cached?.domain?.content?.[key] || fallback || key);
    }

    function moduleEnabled(key) {
        const module = cached?.modules?.modules?.[key];
        return module ? module.enabled !== false : true;
    }

    function applyLabels(root = document) {
        if (!cached) {
            return;
        }

        root.querySelectorAll("[data-domain-label]").forEach(function (el) {
            const key = el.getAttribute("data-domain-label");
            el.textContent = label(key, el.textContent);
        });

        root.querySelectorAll("[data-domain-content]").forEach(function (el) {
            const key = el.getAttribute("data-domain-content");
            el.textContent = text(key, el.textContent);
        });

        root.querySelectorAll("[data-domain-template]").forEach(function (el) {
            el.textContent = String(el.getAttribute("data-domain-template") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            });
        });

        root.querySelectorAll("[data-domain-placeholder]").forEach(function (el) {
            el.setAttribute("placeholder", String(el.getAttribute("data-domain-placeholder") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            }));
        });

        root.querySelectorAll("[data-domain-aria-label]").forEach(function (el) {
            el.setAttribute("aria-label", String(el.getAttribute("data-domain-aria-label") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            }));
        });

        root.querySelectorAll("[data-domain-title]").forEach(function (el) {
            el.setAttribute("title", String(el.getAttribute("data-domain-title") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            }));
        });

        root.querySelectorAll("[data-domain-template]").forEach(function (el) {
            el.textContent = String(el.getAttribute("data-domain-template") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            });
        });

        root.querySelectorAll("[data-domain-placeholder]").forEach(function (el) {
            el.setAttribute("placeholder", String(el.getAttribute("data-domain-placeholder") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            }));
        });

        root.querySelectorAll("[data-domain-aria-label]").forEach(function (el) {
            el.setAttribute("aria-label", String(el.getAttribute("data-domain-aria-label") || "").replace(/\{([a-z_]+)\}/g, function (_, key) {
                return label(key, key);
            }));
        });
    }

    SQ.deployment = {
        load,
        label,
        text,
        moduleEnabled,
        applyLabels,
        get current() {
            return cached;
        }
    };

    document.addEventListener("sq:page-ready", function () {
        if (cached) {
            applyLabels(document);
        }
    });
})(window, document);

/*!
 * ==========================================================
 * SaQshi App Bootstrap v1.0
 * ----------------------------------------------------------
 * Project : SaQshi Open Source
 * File    : app.js
 * Purpose : Main frontend bootstrap file
 * License : GPL-3.0
 * ==========================================================
 *
 * This file initializes:
 * - SQ-UI core
 * - API base URL
 * - Theme
 * - Auth rendering
 * - Sidebar state
 * - Active menu
 * - Chat assistant
 * - Global error handling
 *
 * Load this file after:
 * 1. sq-ui.js
 * 2. storage.js
 * 3. api.js
 * 4. auth.js
 * 5. validator.js
 * 6. upload.js
 * 7. router.js
 * 8. chat.js
 * ==========================================================
 */

(function (window, document) {
    "use strict";

    if (!window.SQ) {
        window.SQ = {};
    }

    const SQ = window.SQ;

    const APP = {
        name: "SaQshi",
        version: "1.0.0",
        apiBaseUrl: "/api",
        loginPage: "/ui/login.html",
        dashboardPage: "/ui/dashboard.html",
        defaultTheme: "light",
        debug: true
    };

    function registerOfflineShell() {
        if (!('serviceWorker' in navigator) || !window.isSecureContext && window.location.hostname !== 'localhost') {
            return;
        }

        window.addEventListener('load', function () {
            navigator.serviceWorker.register('/ui/sw.js?v=20260825-network-first-1').catch(function (error) {
                console.warn('SaQshi offline shell could not be registered.', error);
            });
        });
    }

    function configureApi() {
        if (!SQ.api) {
            return;
        }

        SQ.api.config({
            baseUrl: APP.apiBaseUrl,
            timeout: 30000,
            debug: APP.debug
        });
    }

    function configureAuth() {
        if (!SQ.auth) {
            return;
        }

        SQ.auth.config({
            loginPage: APP.loginPage,
            dashboardPage: APP.dashboardPage
        });
    }

    function initTheme() {
        if (!SQ.storage) {
            return;
        }

        const savedTheme = SQ.storage.get("theme", APP.defaultTheme);

        document.documentElement.setAttribute("data-theme", savedTheme);

        document.querySelectorAll("[data-sq-theme-toggle]").forEach(function (btn) {
            if (btn.dataset.sqThemeBound === "true") {
                return;
            }
            btn.dataset.sqThemeBound = "true";
            btn.addEventListener("click", function () {
                const currentTheme =
                    document.documentElement.getAttribute("data-theme") || APP.defaultTheme;

                const nextTheme = currentTheme === "light" ? "dark" : (currentTheme === "dark" ? "green" : "light");

                document.documentElement.setAttribute("data-theme", nextTheme);
                SQ.storage.set("theme", nextTheme);
                SQ.storage.set("sq-theme", nextTheme);

                if (SQ.toast) {
                    SQ.toast("Theme changed to " + nextTheme, "info");
                }
            });
        });
    }

    function initSidebarState() {
        if (!SQ.storage) {
            return;
        }

        const collapsed = SQ.storage.get("sidebar_collapsed", false);

        if (collapsed) {
            document.body.classList.add("sq-sidebar-collapsed");
        }

        document.querySelectorAll("[data-sq-sidebar-collapse]").forEach(function (btn) {
            btn.addEventListener("click", function () {
                document.body.classList.toggle("sq-sidebar-collapsed");

                SQ.storage.set(
                    "sidebar_collapsed",
                    document.body.classList.contains("sq-sidebar-collapsed")
                );
            });
        });
    }

    function initActiveMenu() {
        if (SQ.router) {
            SQ.router.setActiveMenu("[data-sq-nav]");
        }
    }

    function initUserRender() {
        if (SQ.auth) {
            SQ.auth.renderUser();
        }
    }

    function initChat() {
        /*
         * Chat assistant is loaded as ui/components/chat-assistant.
         * Do not initialize the legacy SQ.chat floating widget here,
         * otherwise two floating help buttons appear on every page.
         */
    }

    function protectPage() {
        const isPublicPage =
            document.body.hasAttribute("data-public-page") ||
            window.location.pathname.endsWith("/login.html") ||
            window.location.pathname.endsWith("/index.html");

        if (isPublicPage) {
            return;
        }

        if (SQ.auth) {
            SQ.auth.requireAuth();
        }
    }

    function bindGlobalActions() {
        document.querySelectorAll("[data-sq-refresh]").forEach(function (btn) {
            btn.addEventListener("click", function () {
                window.location.reload();
            });
        });

        document.querySelectorAll("[data-sq-print]").forEach(function (btn) {
            btn.addEventListener("click", function () {
                window.print();
            });
        });

        document.querySelectorAll("[data-sq-copy]").forEach(function (btn) {
            btn.addEventListener("click", function () {
                const value = btn.getAttribute("data-sq-copy");

                if (SQ.copy) {
                    SQ.copy(value);
                }
            });
        });
    }

    function bindGlobalErrors() {
        window.addEventListener("error", function (event) {
            if (APP.debug) {
                console.error("[SaQshi Error]", event.error || event.message);
            }

            if (SQ.toast) {
                SQ.toast("Unexpected error occurred", "danger");
            }
        });

        window.addEventListener("unhandledrejection", function (event) {
            if (APP.debug) {
                console.error("[SaQshi Promise Error]", event.reason);
            }

            if (SQ.toast) {
                const message =
                    event.reason?.message ||
                    "Something went wrong";

                SQ.toast(message, "danger");
            }
        });
    }

    function init() {
        registerOfflineShell();
        configureApi();
        configureAuth();
        initTheme();
        initSidebarState();
        initActiveMenu();
        initUserRender();
        initChat();
        bindGlobalActions();
        bindGlobalErrors();
        protectPage();

        document.body.classList.add("sq-app-ready");

        if (APP.debug) {
            console.log(APP.name + " UI initialized", APP.version);
        }
    }

    SQ.app = {
        config: function (settings = {}) {
            Object.assign(APP, settings);
        },

        init: init,

        info: function () {
            return {
                name: APP.name,
                version: APP.version,
                apiBaseUrl: APP.apiBaseUrl
            };
        }
    };

    document.addEventListener("DOMContentLoaded", init);

})(window, document);
